@group(0) @binding(0) var<storage, read> b0: array<f32>;
@group(0) @binding(1) var<storage, read> b1: array<f32>;
@group(0) @binding(2) var<storage, read> b2: array<f32>;
@group(0) @binding(3) var<storage, read_write> bout: array<f32>;

@compute @workgroup_size(1024)
fn main(@builtin(local_invocation_index) lid: u32, @builtin(workgroup_id) wid: vec3<u32>, @builtin(num_workgroups) nwg: vec3<u32>) {
    let tid: i32 = i32(lid);
    let bid: i32 = i32(wid.x) + i32(wid.y) * i32(nwg.x);
    if (bid >= 1i) { return; }
    var v_acc0: f32 = 0.0;
    var v_in0: f32 = 0.0;
    var v_in1: f32 = 0.0;
    var v_v0: f32 = 0.0;
    var v_in2: f32 = 0.0;
    var v_v1: f32 = 0.0;
    var n_e: i32 = 0i;
    n_e = ((1024i * bid) + tid);
    if (n_e < 12i) {
        v_acc0 = 0.0;
        for (var n_r0: i32 = 0i; n_r0 < 2i; n_r0 = n_r0 + 1i) {
            v_in0 = b2[(min((((4i * (n_e % 3i)) / 3i) + n_r0), 3i) + (4i * (n_e / 6i)))];
            v_acc0 = (v_acc0 + v_in0);
        }
        v_in1 = b1[((3i * ((n_e / 3i) % 2i)) + (n_e % 3i))];
        v_v0 = (v_acc0 / v_in1);
        v_in2 = b0[((3i * ((n_e / 3i) % 2i)) + (n_e % 3i))];
        v_v1 = (v_v0 / v_in2);
        bout[(((3i * ((n_e / 3i) % 2i)) + (n_e % 3i)) + (6i * (n_e / 6i)))] = v_v1;
    }
}

