    const int tid = threadIdx.x;
    const int bid = blockIdx.x;
    float acc0 = 0.0f, in0 = 0.0f, in1 = 0.0f, v0 = 0.0f, in2 = 0.0f, v1 = 0.0f;
    int e = 0;
    e = ((1024 * bid) + tid);
    if ((e < 12)) {
        acc0 = 0.0f;
        for (int r0 = 0; r0 < 2; r0 += 1) {
            in0 = src2[(min((((4 * (e % 3)) / 3) + r0), 3) + (4 * (e / 6)))];
            acc0 = (acc0 + in0);
        }
        in1 = src1[((3 * ((e / 3) % 2)) + (e % 3))];
        v0 = (acc0 / in1);
        in2 = src0[((3 * ((e / 3) % 2)) + (e % 3))];
        v1 = (v0 / in2);
        dst[(((3 * ((e / 3) % 2)) + (e % 3)) + (6 * (e / 6)))] = v1;
    }
}
